-- KanjiAlive ka_data.csv, normalized for character lookup.
-- The upstream CSV does not provide a separate numeric kanji ID.
-- `id` is generated by Kanotoba; `source_key` preserves upstream `kname`.

PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS kanji (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    character TEXT NOT NULL UNIQUE,
    source_key TEXT,
    stroke_count INTEGER,
    meaning_en TEXT,
    school_grade INTEGER,
    radical_character TEXT,
    radical_order INTEGER,
    radical_stroke_count INTEGER,
    radical_name_ja TEXT,
    radical_name_romaji TEXT,
    radical_meaning_en TEXT,
    radical_position_ja TEXT,
    radical_position_romaji TEXT,
    source_dataset TEXT NOT NULL DEFAULT 'Kanji alive',
    source_revision TEXT NOT NULL DEFAULT 'master',
    imported_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_kanji_school_grade ON kanji(school_grade);
CREATE INDEX IF NOT EXISTS idx_kanji_source_key ON kanji(source_key);
CREATE INDEX IF NOT EXISTS idx_kanji_meaning ON kanji(meaning_en);

CREATE TABLE IF NOT EXISTS kanji_readings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    kanji_id INTEGER NOT NULL,
    reading_type TEXT NOT NULL CHECK (reading_type IN ('kunyomi', 'onyomi')),
    kana TEXT NOT NULL,
    romaji TEXT,
    sort_order INTEGER NOT NULL DEFAULT 0,
    FOREIGN KEY (kanji_id) REFERENCES kanji(id) ON DELETE CASCADE,
    UNIQUE (kanji_id, reading_type, sort_order)
);

CREATE INDEX IF NOT EXISTS idx_kanji_readings_kanji_id ON kanji_readings(kanji_id);
CREATE INDEX IF NOT EXISTS idx_kanji_readings_kana ON kanji_readings(kana);

CREATE TABLE IF NOT EXISTS kanji_examples (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    kanji_id INTEGER NOT NULL,
    word TEXT NOT NULL,
    meaning_en TEXT,
    sort_order INTEGER NOT NULL DEFAULT 0,
    FOREIGN KEY (kanji_id) REFERENCES kanji(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_kanji_examples_kanji_id ON kanji_examples(kanji_id);
